/* eslint-disable no-undef */
// Interactive map of CS teachers & advisors in the NY/NJ/CT tristate area.
// Loads map/data/cs_people.json (generated by src/index.js).

const TRiSTATE_CENTER = [41.15, -74.15];
const DEFAULT_ZOOM = 8;

const state = {
  schools: [],
  markers: [], // { school, marker }
  query: '',
  stateFilter: 'all',
};

const map = L.map('map').setView(TRiSTATE_CENTER, DEFAULT_ZOOM);

// Free basemaps — OpenStreetMap is the default. Switch via the layer control.
const baseLayers = {
  'OpenStreetMap': L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', {
    attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
    maxZoom: 19,
  }),
  'CARTO Light': L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png', {
    attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> &copy; <a href="https://carto.com/attributions">CARTO</a>',
    subdomains: 'abcd',
    maxZoom: 20,
  }),
  'CARTO Dark': L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', {
    attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> &copy; <a href="https://carto.com/attributions">CARTO</a>',
    subdomains: 'abcd',
    maxZoom: 20,
  }),
  'Esri Satellite': L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
    attribution: 'Tiles &copy; Esri &mdash; Source: Esri, Maxar, Earthstar Geographics',
    maxZoom: 19,
  }),
  'Esri Street': L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}', {
    attribution: 'Tiles &copy; Esri &mdash; Source: Esri, HERE, Garmin, INCREMENT P, USGS',
    maxZoom: 19,
  }),
};

baseLayers['OpenStreetMap'].addTo(map);
L.control.layers(baseLayers, null, { position: 'topright', collapsed: true }).addTo(map);

const cluster = L.markerClusterGroup({
  maxClusterRadius: 55,
  spiderfyOnMaxZoom: true,
  showCoverageOnHover: false,
});
map.addLayer(cluster);

function esc(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function personHtml(p) {
  const email = p.email
    ? `<span class="email"><a href="mailto:${esc(p.email)}">${esc(p.email)}</a></span>`
    : '';
  const evidence = p.evidence
    ? `<span class="evidence"> · <a href="${esc(p.evidence)}" target="_blank" rel="noopener">source ↗</a></span>`
    : '';
  return `
    <div class="person">
      <div class="pname">${esc(p.name)}</div>
      <div class="prole">${esc(p.role)}</div>
      ${email}${evidence}
    </div>`;
}

function popupHtml(school) {
  const people = (school.csPeople || [])
    .map(personHtml)
    .join('');
  return `
    <h3>${esc(school.schoolName)}</h3>
    <div class="district">${esc(school.district)} · ${esc(school.city || '')} ${esc(school.state || '')}</div>
    ${people || '<div class="empty-note">No CS people recorded.</div>'}`;
}

function buildMarkers() {
  cluster.clearLayers();
  state.markers = [];

  for (const school of state.schools) {
    if (!Number.isFinite(Number(school.lat)) || !Number.isFinite(Number(school.long))) continue;
    const marker = L.marker([Number(school.lat), Number(school.long)]);
    marker.bindPopup(popupHtml(school), { maxWidth: 340 });
    marker.on('click', () => marker.openPopup());
    cluster.addLayer(marker);
    state.markers.push({ school, marker });
  }
}

function matchesFilter(school) {
  if (state.stateFilter !== 'all' && school.state !== state.stateFilter) return false;
  if (!state.query) return true;
  const q = state.query.toLowerCase();
  const hay = [
    school.schoolName,
    school.district,
    school.city,
    school.state,
    ...(school.csPeople || []).flatMap((p) => [p.name, p.role, p.email]),
  ]
    .join(' ')
    .toLowerCase();
  return hay.includes(q);
}

function renderList() {
  const list = document.getElementById('list');
  const visible = state.schools.filter(matchesFilter);
  list.innerHTML = '';

  if (!visible.length) {
    list.innerHTML = '<li class="empty-note">No schools match.</li>';
    return;
  }

  for (const school of visible) {
    const li = document.createElement('li');
    const people = school.csPeople || [];
    const first = people[0];
    li.innerHTML = `
      <div class="school-name">${esc(school.schoolName)}
        <span class="count-badge">${people.length} ${people.length === 1 ? 'person' : 'people'}</span>
      </div>
      <div class="school-meta">${esc(school.district)} · ${esc(school.city || '')} ${esc(school.state || '')}</div>
      ${
        first
          ? `<span class="person-chip">${esc(first.name)} — <span class="role">${esc(first.role)}</span></span>`
          : ''
      }`;
    li.addEventListener('click', () => {
      map.flyTo([Number(school.lat), Number(school.long)], Math.max(map.getZoom(), 14), {
        duration: 0.5,
      });
      const entry = state.markers.find((m) => m.school === school);
      entry?.marker.openPopup();
    });
    list.appendChild(li);
  }
}

function renderStats() {
  const totalPeople = state.schools.reduce((n, s) => n + (s.csPeople || []).length, 0);
  document.getElementById('stats').textContent =
    `${state.schools.length} schools · ${totalPeople} CS people`;
}

function wireInputs() {
  const search = document.getElementById('search');
  search.addEventListener('input', () => {
    state.query = search.value.trim();
    renderList();
  });

  document.querySelectorAll('.state-pill').forEach((btn) => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.state-pill').forEach((b) => b.classList.remove('active'));
      btn.classList.add('active');
      state.stateFilter = btn.dataset.state;
      renderList();
    });
  });
}

async function init() {
  wireInputs();
  try {
    const res = await fetch('data/cs_people.json');
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    if (!Array.isArray(data)) throw new Error('Unexpected data shape');
    state.schools = data;
    buildMarkers();
    renderStats();
    renderList();
  } catch (e) {
    document.getElementById('stats').textContent = 'No data yet.';
    document.getElementById('list').innerHTML =
      `<li class="empty-note">Could not load data/cs_people.json.<br/><br/>` +
      `Run <code>npm run find</code> first to generate it.<br/>(${esc(e.message)})</li>`;
  }
}

init();
